def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        foreground = [c for c, value in enumerate(row) if value != background]
        if not foreground:
            continue
        last = foreground[-1]
        candidates = []
        for period in range(1, min(5, w)):
            min_length = max(6, 2 * period)
            for start in range(w - min_length + 1):
                for length in range(w - start, min_length - 1, -1):
                    segment = row[start:start + length]
                    if len(set(segment)) < 2:
                        continue
                    if all(segment[i] == segment[i - period] for i in range(period, length)):
                        candidates.append((length, -period, -start, start, period))
                        break
        if candidates:
            _, _, _, start, period = max(candidates)
            for c in range(last + 1, w):
                if row[c] == background and row[start + (c - start) % period] != background:
                    out[r][c] = 1
        elif row[0] != background:
            for c in range(last + 1, w):
                out[r][c] = 1
    return out
