source4='''from collections import Counter

def _best_shift(grid, source_rows, target_rows, background, width):
    best = None
    for shift in range(-width + 1, width):
        inter = union = 0
        for k in range(len(source_rows)):
            src, dst = grid[source_rows[k]], grid[target_rows[k]]
            for c in range(width):
                a = src[c] != background
                d = dst[c + shift] != background if 0 <= c + shift < width else False
                inter += a and d
                union += a or d
        score = inter / union if union else 0
        candidate = (score, -abs(shift), shift)
        if best is None or candidate > best:
            best = candidate
    return best[2]

def _copy_extension(grid, source_rows, target_rows, offset, background, out):
    width = len(grid[0])
    for sr, dr in zip(source_rows, target_rows):
        dst = grid[dr]
        last = max((c for c, v in enumerate(dst) if v != background), default=-1)
        for c, value in enumerate(grid[sr]):
            target = c + offset
            if target > last and target < width and value != background and dst[target] == background:
                out[dr][target] = 1

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [any(v != background for v in row) for row in grid]
    bands = []
    for r, is_active in enumerate(active):
        if is_active:
            if not bands or r != bands[-1][-1] + 1:
                bands.append([r])
            else:
                bands[-1].append(r)
    if len(bands) >= 2 and len(bands[0]) > 1 and all(len(band) == len(bands[0]) for band in bands):
        source = bands[0]
        for target in bands[1:]:
            shift = _best_shift(grid, source, target, background, w)
            if shift >= 0:
                _copy_extension(grid, source, target, shift, background, out)
            else:
                _copy_extension(grid, target, source, -shift, background, out)
        return out
    for r, row in enumerate(grid):
        filled = [c for c, value in enumerate(row) if value != background]
        if filled:
            for c in range(filled[-1] + 1, w):
                out[r][c] = 1
    return out
'''
